export const translatePage = (locale: 'en' | 'es', source: string): string => {
  if (locale === 'en') return source

  const normalized = source.replace(/\s+/gu, ' ').trim()
  const translated = pageCopy[normalized]

  if (translated === undefined) return source

  return source.replace(/\S[\s\S]*\S|\S/u, translated)
}
